import * as Z from './targetless.js?v=36';
import {skillResultsHTML} from './skill-roll-ui.js?v=36';
import * as F from './combat.js?v=36';
import * as V from './saves.js?v=36';
import * as S from './states.js?v=36';
import * as E from './engine.js?v=36';
function setContent(el,html){const old=el.querySelector('.battleBody'),top=old?.scrollTop||0;const content=document.createElement('div');content.innerHTML=html;const button=Array.from(content.children).find(n=>n.matches('button.primary')),footer=document.createElement('div');footer.className='battleFooter';if(button)footer.append(button);el.replaceChildren();const body=document.createElement('div');body.className='battleBody';body.append(...content.childNodes);el.append(body,footer);body.scrollTop=top;}
const teamOf=p=>p?.team??(p?.id?.startsWith('b')?1:0);
const teamName=p=>teamOf(p)?'◆ 蓝队':'▲ 红队';
const label=s=>({attack:'攻击',dodge:'闪避',reset:'重置',idle:'待机',none:'放弃反应',targetless:'投射／烟雾'})[s]||s;
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
function dieHTML(n,status='rolled',extra=''){return `<span class="die ${status}" ${extra}><strong>${n}</strong><small>${({fail:'失败',cancelled:'被抵消',hit:'成功',crit:'暴击',discard:'弃骰',rolled:'待比较',saved:'过保成功',wound:'⚠ 过保失败'})[status]}</small></span>`;}
function diceLine(pool,hits,normal=false){const remaining=[...(hits||[])];return pool.dice.map((n,i)=>{let status;if((Array.isArray(pool.discard)?pool.discard:[pool.discard]).includes(i))status='discard';else if(n>pool.sv)status='fail';else {const ix=remaining.indexOf(n);if(normal||ix>=0){status=E.critical(n,pool.sv)?'crit':'hit';if(ix>=0)remaining.splice(ix,1);}else status='cancelled';}return dieHTML(n,status);}).join('')||'<p class="helper">无掷骰／自动命中</p>';}
export function resultHTML(b,final=true){const r=b.result,p=b.pools;return `<div class="battleHeading"><small>${escape(b.time)} · ${b.fixed?'固定教学骰':'随机 d20'}</small><h2>${escape(b.actor)} · ${escape(b.action)}</h2></div>${skillResultsHTML(b.skillRolls)}${r.details.map(d=>{const q=p.reactions[d.id]||{dice:[],sv:0,name:d.incoming?.targetName||d.id,team:d.incoming?.target?.team??1-p.active.team};let ah=d.zoneOpposed&&r.activeSkill==='targetless'?d.zoneA:d.ah;if(d.activeDodge||r.activeSkill==='reset'&&d.opposed)ah=E.resolveDice(F.kept(p.active),d.aSV??p.active.sv,d.bd,d.bSV).a;return `<article class="duel"><div class="duelLabel">${escape(q.name||d.id)} · ${d.opposed?'面对面检定 / Face to Face':'普通检定 / Normal'}</div><div class="diceSides"><section class="activeDice team-${teamOf(p.active)}"><h3>${teamName(p.active)} · 主动方 · ${p.active.dice.length} 颗${p.active.sd?'（弃 '+p.active.sd+'）':''} · SV ${d.aSV??p.active.sv}</h3><div class="diceRow">${diceLine({...p.active,sv:d.aSV??p.active.sv},ah,r.activeSkill==='reset'&&!d.opposed||r.activeSkill==='targetless'&&!d.zoneOpposed)}</div></section><section class="reactiveDice team-${teamOf(q)}"><h3>${teamName(q)} · 反应方 · ${label(d.action)} · ${q.dice.length} 颗${q.sd?'（弃 '+q.sd+'）':''} · SV ${q.sv}</h3><div class="diceRow">${diceLine(q,d.action==='targetless'?d.zoneB:d.action==='reset'?(d.opposed?E.resolveDice(F.kept(p.active),d.aSV??p.active.sv,d.bd,d.bSV).b:d.bd):d.action==='dodge'?(d.dodged?d.bd:[]):d.bh,d.action==='reset'&&!d.opposed||d.action==='targetless'&&!d.zoneOpposed)}</div></section></div>${final?`<p class="battleOutcome">主动方受 ${d.outgoing.damage} 伤 · 对手受 ${d.incoming.damage} 伤${d.dodged?' · 对手闪避成功':''}</p>`:''}${[d.incoming,d.outgoing].filter(p=>p.targetId).map(p=>saveHTML(p,final,b.after?.find(n=>n.id===p.targetId))).join('')}</article>`;}).join('')||`<div class="diceRow">${diceLine(p.active,F.kept(p.active),true)}</div><p>没有敌方反应。</p>`}${(r.zoneResults||[]).map(z=>`<p class="stagePrompt">${escape(Z.WEAPONS[z.declaration.weapon].name)}：骰 ${z.dice.join(', ')} / SV ${z.sv} · ${z.success?'成功生效（部署物在命令结束放置）':'失败／被抵消，不生成区域或部署物'} · 不产生过保</p>`).join('')}${(r.extraPlans||[]).map(p=>saveHTML(p,final,b.after?.find(n=>n.id===p.targetId))).join('')}<p class="helper">绿色＝未抵消成功；金色＝暴击；灰色＝失败；划线＝被抵消；虚线＝火力组弃骰。多个反应者分别比较同一组主动骰。</p>`;}
export function showBattle(record){const el=document.getElementById('battle');setContent(el,resultHTML(record)+'<button id="closeBattle" class="primary wide">返回战场</button>');if(!el.open)el.showModal();document.getElementById('closeBattle').onclick=()=>el.close();}
export function animatePools(pools,{onChange,onResolve,resume=false}){const el=document.getElementById('battle');let ready=resume;const draw=()=>{const activePending=pools.active.sd&&(Array.isArray(pools.active.discard)?pools.active.discard.length:pools.active.discard===null?0:1)<pools.active.sd,pending=activePending?pools.active:Object.values(pools.reactions).find(p=>p.sd&&(Array.isArray(p.discard)?p.discard.length:p.discard===null?0:1)<p.sd);setContent(el,`<div class="battleHeading"><small>ATTACK & REACTION / 双方检定</small><h2>${ready?(pending?'选择弃骰':'掷骰完成，准备比较'):'正在掷骰…'}</h2></div><p>${pending?(activePending?'主动方先选择所需数量的弃骰。':'反应方现在选择所需数量的弃骰。'):'双方骰值已经固定；继续后比较成功与抵消，再展示命中及过保次数。'}</p>${[pools.active,...Object.values(pools.reactions)].map((p,i)=>`<section class="pool team-${teamOf(p)} ${i?'reactiveDice':'activeDice'}"><h3>${teamName(p)} · ${i?'反应方':'主动方'} · ${escape(p.name)} · ${p.dice.length} 颗 / SV ${p.sv}${p.sd?' / +'+p.sd+' SD':''}</h3>${p.label?`<p class="stagePrompt">${escape(p.label)} · ${p.reason||p.mods.map(m=>m.join(' ')).join(' / ')}</p>`:''}${p.cyberNotice?'<p class="stagePrompt">'+escape(p.cyberNotice)+'</p>':''}${p.mineDodgeSV!==undefined?`<p class="stagePrompt">同一颗骰另以 SV ${p.mineDodgeSV} 闪避地雷（−3，不与无视线惩罚重复叠加）</p>`:''}<div class="diceRow ${ready?'':'rolling'}">${p.dice.map((n,j)=>`<button class="dieChoice" data-pool="${p.id}" data-index="${j}" ${!ready||pending!==p?'disabled':''} aria-label="${p.name} 第 ${j+1} 颗：${n}">${dieHTML(n,(Array.isArray(p.discard)?p.discard:[p.discard]).includes(j)?'discard':'rolled')}</button>`).join('')||'<span class="helper">无攻击骰／自动命中</span>'}</div></section>`).join('')}<button id="compareDice" class="primary wide" ${!ready||pending?'disabled':''}>比较骰子 → 查看命中</button><p class="micro">动画仅展示这次已生成的骰值，不重新掷骰。</p>`);el.querySelectorAll('[data-pool]').forEach(b=>b.onclick=()=>{const p=b.dataset.pool===pools.active.id?pools.active:pools.reactions[b.dataset.pool];if(p.sd>1){p.discard=Array.isArray(p.discard)?p.discard:[];if(!p.discard.includes(+b.dataset.index))p.discard.push(+b.dataset.index);}else p.discard=+b.dataset.index;onChange();draw();});document.getElementById('compareDice').onclick=onResolve;};draw();if(!el.open)el.showModal();el.oncancel=e=>e.preventDefault();if(!resume)setTimeout(()=>{ready=true;draw();},1100);}

function basis(t){return `${t.stat} ${t.rawBase??t.base}${t.reduction==='half'?` ÷2↑ = ${t.base}`:t.reduction==='zero'?' → 0':''}${t.stat==='PH'?' −6':` ＋ PS ${t.ps}${t.cover?' ＋ 掩体3':''}`}`;}
function saveHTML(p,final=false,after){const target=structuredClone(p.target);if(final){if(after)Object.assign(target,after);else S.apply(target,p.damage,p.effects);}return `<section class="saveCard team-${teamOf(p.target)}"><h3>${teamName(p.target)} · ${escape(p.targetName)} · ${escape(V.AMMO[p.ammo]||p.ammo)}</h3>${p.mine?`<p class="stagePrompt">地雷自动命中${p.dodgeSV!==null?` · 闪避骰 ${p.dodgeDice.join(', ')} / SV ${p.dodgeSV} · ${p.avoided?'成功避开':'未能避开，不获得闪避移动'}`:''}</p>`:''}<div class="saveCounts"><b>${p.hits}<small>未抵消命中</small></b><b>${p.criticals}<small>其中暴击</small></b><b>${p.initialCount}<small>初始过保次数</small></b></div>${!p.initialCount?'<p>没有命中，无需过保。</p>':''}${p.pending.length&&!p.saves.length?`<p>${p.pending.map(t=>`${basis(t)} = <b>SV ${t.sv}</b>${t.critical?'（暴击附加）':''}`).join('<br>')}</p>`:''}${p.saves.length?`<div class="saveRolls">${p.saves.map(t=>`<div class="saveDie">${dieHTML(t.die,t.fail?'wound':'saved')}<small>${basis(t)}<br>SV ${t.sv} · 第 ${t.round} 轮${t.critical?' · 暴击附加':''}</small></div>`).join('')}</div>`:''}${p.pending.length&&p.saves.length?`<p class="warning">持续伤害尚有 ${p.pending.length} 次追加过保。</p>`:''}${final?`<p class="stateResult">${p.damage} 点伤害（本组过保） · 最终状态 ${S.labels(target).join(' / ')||'正常'} · 剩余 ${target.attribute||'VITA'} ${Math.max(0,target.hp)}</p>`:''}</section>`;}
export function animateSaves(record,{onRoll,onCommit,resume=false}){const el=document.getElementById('battle');let rolling=false;const draw=()=>{const plans=V.allPlans(record.result),pending=plans.reduce((n,p)=>n+p.pending.length,0),rolled=plans.some(p=>p.saves.length);setContent(el,`<div class="battleHeading"><small>命中 → 过保检定 → 伤害与状态</small><h2>${rolling?'正在掷过保骰…':rolled?(pending?'持续伤害：继续过保':'过保完成，确认伤害'):'命中已确定，准备过保'}</h2></div><p>未抵消的命中才产生过保。d20 ≤ 成功值为成功；此阶段不会重新掷攻击骰。</p>${!rolled&&!rolling?`<details><summary>查看双方拼骰与抵消</summary>${resultHTML(record,false)}</details>`:''}${rolling?`<div class="diceRow rolling">${Array.from({length:Math.max(1,record.lastBatch||1)},()=>dieHTML('?', 'rolled')).join('')}</div>`:plans.map(p=>saveHTML(p,false)).join('')||'<p>没有命中，无需过保。</p>'}<button id="rollSaves" class="primary wide" ${rolling?'disabled':''}>${pending?'掷过保骰'+(rolled?' · 持续伤害下一轮':''):'确认伤害与状态 → 返回结算'}</button><p class="micro">${rolled?'已掷出的点数已保存，刷新不会重掷。':'先核对双方命中次数和过保属性，再开始掷骰。'}</p>`);document.getElementById('rollSaves').onclick=()=>{if(rolling)return;if(!pending){onCommit();return;}record.lastBatch=pending;onRoll();rolling=true;draw();setTimeout(()=>{rolling=false;draw();},1100);};};draw();if(!el.open)el.showModal();el.oncancel=e=>e.preventDefault();}
